ST.xhtml:p:
IF bUseUpSignal AND boCylUp AND NOT boCylDown THEN
  Ton_UpDelay(IN :=FALSE);
  Ton_Down(IN := FALSE);
  Ton_DownDelay(IN :=FALSE);
  IF bUpInplace THEN
    bCylStateToHMI :=TRUE;
    bCylDownDone :=FALSE;
    bCylUpDone :=TRUE;
    bCylState := TRUE;
    Ton_Up(IN := FALSE);
    bCylUpNoSignalAlarm := FALSE;
  ELSE
    IF NOT bCylState THEN
      Ton_Up(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinderUpOverDelayTime)));
      IF Ton_Up.Q THEN
        bCylUpNoSignalAlarm := TRUE;
        Ton_Up(IN := FALSE);
      END_IF;
    END_IF;  
  END_IF;   
  IF bCylState THEN
    IF bUpInplaceNoFilter THEN
      bCylUpNoSignalAlarm := FALSE;
    ELSE
      bCylUpNoSignalAlarm := TRUE;
    END_IF;
  END_IF;
ELSE  
  bCylUpNoSignalAlarm := FALSE;
  IF boCylUp AND NOT boCylDown THEN
    Ton_Down(IN := FALSE);
    Ton_Up(IN := FALSE);
    Ton_DownDelay(IN :=FALSE);
    Ton_UpDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinderUpDelayTime)));
    IF Ton_UpDelay.Q THEN
      Ton_UpDelay(IN :=FALSE);
      bCylStateToHMI :=TRUE;
      bCylUpDone :=TRUE;
      bCylDownDone :=FALSE;
      bCylState := TRUE;
    END_IF;
  END_IF;
END_IF;  
IF bUseDownSignal AND boCylDown AND NOT boCylUp THEN 
  Ton_Up(IN := FALSE);
  Ton_DownDelay(IN :=FALSE);
  Ton_UpDelay(IN :=FALSE);
  IF bDownInplace THEN
    bCylStateToHMI :=FALSE;
    bCylDownDone :=TRUE;
    bCylUpDone :=FALSE;
    bCylState := FALSE;
    Ton_Down(IN := FALSE);
    bCylDownNoSignalAlarm := FALSE;
  ELSE
    IF bCylState THEN
      Ton_Down(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinderDownOverDelayTime)));
      IF Ton_Down.Q THEN
        bCylDownNoSignalAlarm := TRUE;
        Ton_Down(IN := FALSE);
      END_IF;
    END_IF;
  END_IF;
  IF NOT bCylState THEN
    IF bDownInplaceNoFilter THEN
      bCylDownNoSignalAlarm := FALSE;
    ELSE
      bCylDownNoSignalAlarm := TRUE;
    END_IF;
  END_IF;
ELSE  
  bCylDownNoSignalAlarm := FALSE;
  IF NOT boCylUp AND boCylDown THEN
    Ton_Up(IN := FALSE);
    Ton_Down(IN := FALSE);
    Ton_UpDelay(IN :=FALSE);
    Ton_DownDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinderDownDelayTime)));
    IF Ton_DownDelay.Q THEN
      Ton_DownDelay(IN :=FALSE);
      bCylStateToHMI :=FALSE;
      bCylUpDone :=FALSE;
      bCylDownDone :=TRUE;
      bCylState := FALSE;
    END_IF;
  END_IF;
END_IF; 


(*打开输出口控制 气缸使用延时的状态切换 状态*)
IF bArrayConfigOutputUp AND NOT bUseUpSignal AND boCylUp THEN
  bCylStateToHMI :=TRUE;
  bCylUpDone :=TRUE;
  bCylState := TRUE;
  bCylDownDone:=FALSE;
  bArrayConfigOutputUp_FB := FALSE;
ELSE
  bArrayConfigOutputUp_FB := FALSE;  
END_IF;
IF bArrayConfigOutputDown AND NOT bUseDownSignal AND boCylDown THEN
  bCylStateToHMI :=FALSE;
  bCylUpDone :=FALSE;
  bCylState := FALSE;
  bCylDownDone:=TRUE;
  bArrayConfigOutputDown_FB := FALSE;
ELSE
  bArrayConfigOutputDown_FB := FALSE;  
END_IF;
